#include <bits/stdc++.h>
using namespace std;
int a[100005],b[100005],g[100005],k[100005];
int main()
{
    int n;
    cin >> n;
    for(int i = 1;i <= n;i++) cin >> a[i] >> b[i] >> g[i] >> k[i];
    int x,y;
    cin >> x >> y;
    for(int i = n;i >= 1;i--)
    {
        if(x >= a[i] && x <= a[i]+g[i] && y >= b[i] && y <= b[i]+k[i])
        {
            cout << i << endl;
            return 0;
        }
    }
    cout << -1 << endl;
    return 0;
}
